        this.hysteresis = this.hysteresisFor(first);
      }
      this.origin = centroid(this.touches.values());
      this.adjust = ZERO;
      this.raw = ZERO;
      this.offset = ZERO;
      this.tracker.reset();
      this.tracker.add(this.origin.x, this.origin.y, event.time);
    } else {
      this.rebase(new Set(touches.map(touch => touch.id)), 'added');
    }
