  markedRoots.set(element, root);
  return true;
}

/** `root` no longer holds `element`'s mark; its last mark takes the rules. */
function releaseMark(element: Element, root: RuleRoot): void {
  const entry = sheets.get(root);
  if (entry == null) {
    return;
