/** A running or idle edge autoscroll. */
export interface EdgeAutoscroll {
  /** Starts the timer when `step` is not 0, and stops it when it is. */
  update(): void;
  /** Stops the timer. */
  stop(): void;
  /** Whether the timer runs. */
