const CONTENT_OPTIONS: MutationObserverInit = {
  characterData: true,
  childList: true,
  subtree: true,
};

interface SharedObserver {
  readonly observer: MutationObserver;
  readonly callbacks: Map<Node, Set<MutationCallback>>;
  readonly deliver: (records: MutationRecord[]) => void;
